INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Methode zur Problemlösung immer mit Planen beginnt?', 2, '[{"text": "Nein", "correct": true, "because": "Informieren kommt zuerst"}, {"text": "Ja", "correct": false, "because": "Schritte sind fest"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt kommt in einer strukturierten Methode als erstes?', 3, '[{"text": "Informieren", "correct": true, "because": "Sammelt Basisdaten"}, {"text": "Planen", "correct": false, "because": "Folgt später"}, {"text": "Realisieren", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen gehören zu einer systematischen Problemlösung?', 5, '[{"text": "Informieren", "correct": true, "because": "Erhebt Daten"}, {"text": "Planen", "correct": true, "because": "Legt Vorgehen fest"}, {"text": "Kontrollieren", "correct": true, "because": "Überwacht Fortschritt"}, {"text": "Designen", "correct": false, "because": "Kein IPERKA-Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Informieren sammelt Daten. b) Entscheiden ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Entscheiden ist Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein IT-Projekt strukturiere?', 4, '[{"text": "Planung", "correct": false, "because": "Definiert Vorgehen"}, {"text": "Kontrolle", "correct": false, "because": "Prüft Fortschritt"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Methode wie IPERKA nur für große Projekte ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für kleine Aufgaben"}, {"text": "Ja", "correct": false, "because": "Universell einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt hilft mir, die beste Lösung für ein IT-Problem auszuwählen?', 3, '[{"text": "Entscheiden", "correct": true, "because": "Wählt Option"}, {"text": "Realisieren", "correct": false, "because": "Umsetzung"}, {"text": "Auswerten", "correct": false, "because": "Nachbereitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine strukturierte Methode in der IT?', 5, '[{"text": "Klarheit", "correct": true, "because": "Definiert Schritte"}, {"text": "Effizienz", "correct": true, "because": "Vermeidet Chaos"}, {"text": "Lernmöglichkeiten", "correct": true, "because": "Auswertung verbessert"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Kontrollieren den Fortschritt prüft und b) Auswerten am Anfang kommt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auswerten ist am Ende"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um ein IT-Problem systematisch zu lösen?', 4, '[{"text": "Datenanalyse", "correct": false, "because": "Teil von Informieren"}, {"text": "Planung", "correct": false, "because": "Legt Vorgehen fest"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Realisieren der erste Schritt?', 2, '[{"text": "Nein", "correct": true, "because": "Informieren kommt zuerst"}, {"text": "Ja", "correct": false, "because": "Späterer Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen helfen bei der Fehleranalyse in einem IT-Projekt?', 4, '[{"text": "Kontrollieren", "correct": true, "because": "Prüft Ablauf"}, {"text": "Auswerten", "correct": true, "because": "Analysiert Ergebnisse"}, {"text": "Designen", "correct": false, "because": "Kein IPERKA-Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Methode wie IPERKA keine Planung braucht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Planen ist zentral"}, {"text": "Ja", "correct": false, "because": "Planung essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer systematischen Methode?', 3, '[{"text": "Strukturierte Lösung", "correct": true, "because": "Klarer Ablauf"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Faktor"}, {"text": "Designverbesserung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Auswerten verbessert zukünftige Projekte. b) Realisieren ist der letzte Schritt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auswerten ist letzter Schritt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Planen bei einem IT-Projekt?', 4, '[{"text": "Vorgehen definieren", "correct": true, "because": "Legt Schritte fest"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Anderer Zweck"}, {"text": "Design anpassen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Kontrollieren nur am Ende kommt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch währenddessen"}, {"text": "Ja", "correct": false, "because": "Fortlaufend möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Methode wie IPERKA nützlich?', 5, '[{"text": "Struktur", "correct": true, "because": "Klarer Ablauf"}, {"text": "Flexibilität", "correct": true, "because": "Anpassbar"}, {"text": "Lernprozess", "correct": true, "because": "Auswertung hilft"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Informieren nur für große Projekte?', 3, '[{"text": "Nein", "correct": true, "because": "Für alle Größen"}, {"text": "Ja", "correct": false, "because": "Universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einer strukturierten Methode?', 4, '[{"text": "Netzwerkproblem lösen", "correct": true, "because": "Systematischer Ansatz"}, {"text": "Webdesign erstellen", "correct": false, "because": "Kreativer Fokus"}, {"text": "Daten komprimieren", "correct": false, "because": "Technischer Prozess"}]');
